let currentUser=null,currentProfile=null,favoriteIds=[],likedIds=[],historyIds=[],authReady=false,stateLoadId=0,gamesLoadState='loading',recordedPlayKey='',recordingPlayKey='',notificationBound=false,notificationChannel=null;const sb=window.divisionSupabase;const user=()=>currentUser?{...currentUser,username:currentProfile?.username||currentUser.user_metadata?.username||currentUser.email?.split('@')[0]||'Player',email:currentUser.email,avatar_url:currentProfile?.avatar_url||null}:null;(()=>{let u=read('division_user',null);if(u&&u.password){delete u.password;write('division_user',u)}let a=read('division_accounts',[]);if(a.some(x=>x&&Object.prototype.hasOwnProperty.call(x,'password'))){a=a.map(x=>{let copy={...x};delete copy.password;return copy});write('division_accounts',a)}})();
